#!/bin/sh
# Scaffold for ho-report-top-n: writes the task's files into the current directory.
set -e
mkdir -p examples scripts && printf '# order report\n\n    python3 report.py examples/orders.csv\n\nprints each customer'\''s total spend, biggest first, then a TOTAL line.\n\nBefore handing changes over, run `python3 scripts/check.py`. It runs the\nexample input in examples/ and compares the output with the *.expected files.\n' > README.md && printf '"""Per-customer spend report from an orders CSV."""\nimport csv\nimport sys\n\n\ndef load(path):\n    """Return {customer: total in cents}."""\n    totals = {}\n    with open(path, newline="") as f:\n        for row in csv.DictReader(f):\n            cents = round(float(row["amount"]) * 100)\n            totals[row["customer"]] = totals.get(row["customer"], 0) + cents\n    return totals\n\n\ndef money(cents):\n    return "%%d.%%02d" %% divmod(cents, 100)\n\n\ndef render(totals):\n    lines = []\n    for name, cents in sorted(totals.items(), key=lambda kv: -kv[1]):\n        lines.append("%%-10s %%10s" %% (name, money(cents)))\n    lines.append("%%-10s %%10s" %% ("TOTAL", money(sum(totals.values()))))\n    return "\\n".join(lines)\n\n\ndef main(argv):\n    print(render(load(argv[1])))\n\n\nif __name__ == "__main__":\n    main(sys.argv)\n' > report.py && printf 'customer,amount\nana,19.99\nbo,5.00\nana,30.01\ncy,12.50\nbo,7.25\ndee,100.00\ncy,0.10\n' > examples/orders.csv && printf 'dee            100.00\nana             50.00\ncy              12.60\nbo              12.25\nTOTAL          174.85\n' > examples/all.expected && printf 'dee            100.00\nana             50.00\nTOTAL          174.85\n' > examples/top2.expected && printf '"""Run report.py on the example input and compare with the stored output."""\nimport os\nimport subprocess\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nCASES = [\n    ("all.expected", []),\n    ("top2.expected", ["--top", "2"]),\n]\n\n\ndef run(extra):\n    cmd = [sys.executable, "report.py", "examples/orders.csv"] + extra\n    return subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True)\n\n\ndef main():\n    failed = 0\n    for expected_name, extra in CASES:\n        with open(os.path.join(ROOT, "examples", expected_name)) as f:\n            expected = f.read()\n        result = run(extra)\n        if result.returncode != 0 or result.stdout != expected:\n            failed += 1\n            print("FAIL", expected_name)\n            print("--- expected")\n            print(expected, end="")\n            print("--- got")\n            print(result.stdout + result.stderr, end="")\n        else:\n            print("ok  ", expected_name)\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n' > scripts/check.py
